package cli

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/shadeform/shadeform-cli/internal/client"
	"github.com/shadeform/shadeform-cli/internal/config"
	"github.com/shadeform/shadeform-cli/internal/flagutil"
	"github.com/shadeform/shadeform-cli/internal/output"
	"github.com/shadeform/shadeform-cli/internal/selfupdate"
	"github.com/shadeform/shadeform-cli/internal/usage"
	"github.com/spf13/cobra"
	"golang.org/x/term"
)

// `shade update` and the once-a-day update notice are hand-written, not
// generated by Speakeasy. Everything that touches GitHub or the file system
// lives in internal/selfupdate; this file is the cobra command and the glue
// that decides when the notice may print.

const (
	updateVersionFlag = "version"
	updateCheckFlag   = "check"
)

// Hooks the tests replace so no test talks to GitHub or swaps a real binary.
var (
	// updateClient builds the GitHub client used by update and the notice.
	updateClient = func(timeout time.Duration) *selfupdate.Client {
		c := selfupdate.NewClient(Version)
		c.HTTP.Timeout = timeout
		return c
	}
	// updateTarget is the binary to replace.
	updateTarget = selfupdate.ExecutablePath
	// updateSource classifies that binary.
	updateSource = selfupdate.DetectSource
	// interactiveTerminal is the TTY gate for the notice: a person at a
	// terminal, with nothing piped. Both streams are checked so a piped
	// stdout (shade ... | jq) is left alone even though the notice goes to
	// stderr.
	interactiveTerminal = func() bool {
		return term.IsTerminal(int(os.Stdout.Fd())) && term.IsTerminal(int(os.Stderr.Fd()))
	}
)

// isReleaseBuild is true for binaries GoReleaser built: it stamps BuildTime
// through ldflags, and nothing else does. go build and go install leave it
// empty, so they are never told to update and never updated in place.
func isReleaseBuild() bool { return BuildTime != "" }

func initUpdateCmd(parent *cobra.Command) {
	cmd := &cobra.Command{
		Use:   "update",
		Short: "Update shade to the latest release",
		Long: `Update shade to the latest release from GitHub.

shade downloads the archive for this platform from
https://github.com/` + selfupdate.Repo + `/releases, verifies it against the
release's checksums.txt, and replaces the running binary in place. The old
binary is only swapped out once the new one is fully written and verified.

A binary installed with Homebrew or go install is not touched; the command
prints the matching upgrade command instead.

shade also mentions a newer release, once a day at most, after a command
finishes at an interactive terminal. Set ` + selfupdate.NoCheckEnv + `=1 to turn that
off. The check is a single anonymous request to api.github.com and sends
nothing about you or your account.`,
		Example: `  shade update
  shade update --check
  shade update --version v0.3.1`,
		Annotations: map[string]string{"speakeasy_settings_command": "true"},
		Args:        cobra.NoArgs,
		RunE:        runUpdateCmd,
	}
	cmd.Flags().String(updateVersionFlag, "", "Install this release (e.g. v0.3.1) instead of the latest")
	cmd.Flags().Bool(updateCheckFlag, false, "Only report whether a newer release exists; do not install")
	parent.AddCommand(cmd)
	usage.RegisterRootCommand(cmd)
}

// updateResult is what update reports, in prose or as JSON.
type updateResult struct {
	Current   string `json:"current_version"`
	Latest    string `json:"latest_version,omitempty"`
	Updated   bool   `json:"updated"`
	Installed string `json:"installed_version,omitempty"`
	Path      string `json:"path,omitempty"`
	Source    string `json:"source,omitempty"`
	Message   string `json:"message,omitempty"`
}

func runUpdateCmd(cmd *cobra.Command, args []string) error {
	if usage.UsageRequested(cmd) {
		return usage.EmitSchema(cmd, cmd.OutOrStdout())
	}
	checkOnly, _ := flagutil.GetBoolFlag(cmd, updateCheckFlag)
	wanted, _ := flagutil.GetStringFlag(cmd, updateVersionFlag)
	wanted = strings.TrimSpace(wanted)

	if client.IsDryRun(cmd) {
		what := "the latest release"
		if wanted != "" {
			what = "release " + wanted
		}
		msg := "update would download " + what + " from github.com/" + selfupdate.Repo + " and replace this binary (no network, nothing was changed)."
		if checkOnly {
			msg = "update --check would ask github.com/" + selfupdate.Repo + " for the latest release (no network, nothing was changed)."
		}
		dryRunLocalNoop(cmd, msg)
		return nil
	}

	ctx := cmd.Context()
	if ctx == nil {
		ctx = context.Background()
	}
	target, err := updateTarget()
	if err != nil {
		return fmt.Errorf("locating the shade binary: %w", err)
	}
	source := updateSource(target, isReleaseBuild())
	res := updateResult{Current: "v" + strings.TrimPrefix(Version, "v"), Path: target, Source: source.String()}

	// Resolving the release is harmless for every source, so --check works
	// for a Homebrew install too; only the replace step is refused.
	up := selfupdate.NewUpdater(updateClient(30 * time.Second))
	plan, err := up.Resolve(ctx, wanted)
	if errors.Is(err, selfupdate.ErrNoRelease) {
		if wanted != "" {
			return fmt.Errorf("no release %s at github.com/%s/releases", wanted, selfupdate.Repo)
		}
		return fmt.Errorf("github.com/%s has no releases yet", selfupdate.Repo)
	}
	if err != nil {
		return fmt.Errorf("checking for updates: %w", err)
	}
	res.Latest = plan.Release.Tag
	newer := selfupdate.IsNewer(plan.Release.Tag, Version)
	same := !newer && strings.TrimPrefix(plan.Release.Tag, "v") == strings.TrimPrefix(Version, "v")

	if checkOnly {
		switch {
		case newer:
			res.Message = fmt.Sprintf("A new version of shade is available (%s -> %s). Run: shade update", res.Current, plan.Release.Tag)
		case same:
			res.Message = fmt.Sprintf("shade %s is the latest release.", res.Current)
		default:
			res.Message = fmt.Sprintf("shade %s is newer than the latest release %s.", res.Current, plan.Release.Tag)
		}
		return reportUpdate(cmd, res)
	}

	// Without --version only move forward; with it, install exactly that.
	if wanted == "" && !newer {
		if same {
			res.Message = fmt.Sprintf("shade %s is already the latest release.", res.Current)
		} else {
			res.Message = fmt.Sprintf("shade %s is newer than the latest release %s; nothing to do. Use --version to install a specific release.", res.Current, plan.Release.Tag)
		}
		return reportUpdate(cmd, res)
	}
	if wanted != "" && same {
		res.Message = fmt.Sprintf("shade %s is already installed.", res.Current)
		return reportUpdate(cmd, res)
	}
	if !source.Updatable() {
		return errors.New(source.Advice())
	}
	if err := selfupdate.CheckWritable(target); err != nil {
		return permissionAdvice(err)
	}

	errOut := cmd.ErrOrStderr()
	if !output.IsMachineMode(cmd) {
		fmt.Fprintf(errOut, "Downloading shade %s (%s)...\n", plan.Release.Tag, plan.AssetName)
	}
	binary, err := up.Fetch(ctx, plan)
	if errors.Is(err, selfupdate.ErrChecksumMismatch) {
		return fmt.Errorf("%w\nThe current binary was not changed. Try again; if it keeps happening, report it at https://github.com/%s/issues", err, selfupdate.Repo)
	}
	if err != nil {
		return err
	}
	if err := selfupdate.Replace(target, binary); err != nil {
		return permissionAdvice(err)
	}
	res.Updated = true
	res.Installed = plan.Release.Tag
	res.Message = fmt.Sprintf("Updated shade %s -> %s at %s", res.Current, plan.Release.Tag, target)

	// The cache now knows the answer; refresh it so the notice does not
	// fire again for a version we just installed.
	_ = selfupdate.SaveCache(selfupdate.CachePath(config.GetConfigPath()), selfupdate.Cache{
		CheckedAt: time.Now().UTC(), Latest: plan.Release.Tag,
	})
	return reportUpdate(cmd, res)
}

// permissionAdvice turns an unwritable install directory into the two ways
// out; any other error passes through unchanged.
func permissionAdvice(err error) error {
	var perm *selfupdate.PermissionError
	if !errors.As(err, &perm) {
		return err
	}
	return fmt.Errorf("%w\nThe current binary was not changed. Either rerun with sudo:\n  sudo %s update\nor reinstall somewhere you can write:\n  curl -fsSL https://raw.githubusercontent.com/%s/main/scripts/install.sh | SHADEFORM_INSTALL_DIR=$HOME/.local/bin bash",
		err, os.Args[0], selfupdate.Repo)
}

func reportUpdate(cmd *cobra.Command, res updateResult) error {
	if output.IsMachineMode(cmd) {
		return output.LocalResult(cmd, asMap(res))
	}
	fmt.Fprintln(cmd.OutOrStdout(), res.Message)
	return nil
}

// maybeNotifyUpdate runs after every command. It prints at most one line to
// stderr, and only when every gate in selfupdate.ShouldNotify holds.
func maybeNotifyUpdate(ctx context.Context, executed *cobra.Command, cmdErr error) {
	if executed == nil {
		return
	}
	if ctx == nil {
		ctx = context.Background()
	}
	name := executed.Name()
	skip := name == "update" || name == "completion" || name == "__complete" || name == "__completeNoDesc" || name == "help"
	for p := executed.Parent(); p != nil && !skip; p = p.Parent() {
		if p.Name() == "completion" {
			skip = true
		}
	}
	jq, _ := flagutil.GetStringFlag(executed, "jq")
	gate := selfupdate.Gate{
		CurrentVersion: Version,
		ReleaseBuild:   isReleaseBuild(),
		CommandFailed:  cmdErr != nil,
		InteractiveTTY: interactiveTerminal(),
		AgentMode:      output.IsAgentMode(),
		OutputFormat:   flagutil.ResolveOutputFormat(executed, config.GetString("output-format"), output.IsAgentMode()),
		JQ:             jq != "",
		DryRun:         client.IsDryRun(executed),
		SkipCommand:    skip,
	}
	if !selfupdate.ShouldNotify(gate) {
		return
	}
	checker := &selfupdate.Checker{
		Client:    updateClient(3 * time.Second),
		CachePath: selfupdate.CachePath(config.GetConfigPath()),
	}
	checker.Notify(ctx, gate, executed.ErrOrStderr())
}
